// Get the original lead data directly from the Webhook node
const webhookData = $('Webhook').first().json;

const name = webhookData.body?.name || webhookData.name || "";
const email = webhookData.body?.email || webhookData.email || "";
const message = webhookData.body?.message || webhookData.message || "";
const date = new Date().toISOString();

// Get Gemini's response from the current HTTP Request node
let geminiText = "";

try {
  const response = $json;

  geminiText =
    response?.candidates?.[0]?.content?.parts?.[0]?.text ||
    response?.candidates?.[0]?.content?.parts
      ?.map(part => part.text || "")
      .join("") ||
    "";

  if (!geminiText && typeof response?.text === "string") {
    geminiText = response.text;
  }

  if (!geminiText && typeof response?.output === "string") {
    geminiText = response.output;
  }
} catch (error) {
  geminiText = "";
}

let cleanedText = geminiText.trim();

cleanedText = cleanedText
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let classification;

try {
  classification = JSON.parse(cleanedText);
} catch (firstError) {
  try {
    const start = cleanedText.indexOf("{");
    const end = cleanedText.lastIndexOf("}");

    if (start !== -1 && end !== -1 && end > start) {
      const possibleJson = cleanedText.substring(start, end + 1);
      classification = JSON.parse(possibleJson);
    } else {
      throw new Error("No JSON object found");
    }
  } catch (secondError) {
    classification = {
      is_hot: false,
      urgency: "low",
      category: "other",
      reasoning: "Gemini returned an invalid response; automatically treated as cold for safety."
    };
  }
}

if (typeof classification.is_hot !== "boolean") {
  classification.is_hot = String(classification.is_hot).toLowerCase() === "true";
}

if (!["low", "medium", "high"].includes(classification.urgency)) {
  classification.urgency = "low";
}

if (!["sales", "support", "spam", "other"].includes(classification.category)) {
  classification.category = "other";
}

if (
  typeof classification.reasoning !== "string" ||
  !classification.reasoning.trim()
) {
  classification.reasoning = "Classification completed without a valid reasoning message.";
}

return [
  {
    json: {
      name,
      email,
      message,
      is_hot: classification.is_hot,
      urgency: classification.urgency,
      category: classification.category,
      reasoning: classification.reasoning,
      date
    }
  }
];

